        Expr denom = cast<num_t>(5 * m);
        init_A(j, i) = num / denom;
    }

    // -------------------------------------------------------------------------
    // Schedule for initialization
    //
    // We do a one-time initialization, but for realistic problem sizes
    // it's still worth vectorizing and parallelizing.
    // -------------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // x is 1-D, contiguous in j
    init_x.compute_root()
          .vectorize(j, vec_width)
          .parallel(j);

    // A(j, i): j is fastest-varying (inner), i is outer
    init_A.compute_root()
          .parallel(i)          // parallel over rows i
          .vectorize(j, vec_width);  // vector over contiguous j

    // Realize into the provided Buffers
    init_x.realize(x, target);
    init_A.realize(A, target);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A(i,j) in C becomes A(j,i) with shape (n, m) in Halide.
    Halide::Buffer<num_t, 2> A(n, m);  // [j, i]
    Halide::Buffer<num_t, 1> x(n);     // [j]
    Halide::Buffer<num_t, 1> y(n);     // [j] output

    // Initialize data
    init_array(m, n, A, x);

    // Wrap A and x as ImageParams so the pipeline is decoupled from
    // the concrete Buffers and can be JIT-compiled independently.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // We know the memory layout: first dimension contiguous
    A_param.dim(0).set_stride(1);          // A(j, i): j contiguous
    x_param.dim(0).set_stride(1);          // x(j): contiguous

    // Vars and reduction domains
    Var i("i"), j("j");
    // Use the runtime extents of A to define the reduction ranges,
    // mirroring the original C loops over N and M.
    RDom r1(0, A.dim(0).extent(), "r1");  // j in [0..n-1]
    RDom r2(0, A.dim(1).extent(), "r2");  // i in [0..m-1]

    // -------------------------------------------------------------------------
    // Kernel translation
    //
    // Original C kernel:
    //
    //   for (i = 0; i < _PB_N; i++)
    //     y[i] = 0;
    //   for (i = 0; i < _PB_M; i++) {
    //     tmp[i] = 0;
    //     for (j = 0; j < _PB_N; j++)
    //       tmp[i] = tmp[i] + A[i][j] * x[j];
    //     for (j = 0; j < _PB_N; j++)
    //       y[j] = y[j] + A[i][j] * tmp[i];
    //   }
    //
    // This is:
    //   tmp[i] = sum_j A[i][j] * x[j];
    //   y[j]   = sum_i A[i][j] * tmp[i];
    //
    // With our layout A(j,i):
    //   tmp(i) = sum_j A(j,i) * x(j);
    //   y(j)   = sum_i A(j,i) * tmp(i);
    // -------------------------------------------------------------------------
    Func tmp("tmp"), y_func("y_func");

    // tmp(i) = sum over r1 (j) of A(j,i) * x(j)
    tmp(i) = cast<num_t>(0);
    tmp(i) += A_param(r1, i) * x_param(r1);

    // y(j) = sum over r2 (i) of A(j,i) * tmp(i)
    y_func(j) = cast<num_t>(0);
    y_func(j) += A_param(j, r2) * tmp(r2);

    // -------------------------------------------------------------------------
    // Schedule
    // -------------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Compute tmp once in full, paralleling across i (rows), and
    // vectorizing the inner reduction over r1 (columns, contiguous).
    tmp.compute_root();
    tmp.update()
        .parallel(i)
        .vectorize(r1, vec_width);

    // Compute y at root. We'll:
    //  - tile / split the output index j into [jo, ji]
    //  - parallelize across jo (tiles of j)
    //  - keep ji contiguous and vectorized
    //  - order loops for the update as jo (outer), r2 (middle), ji (inner)
    //    so that within each tile we still walk A and y in row-major order.
    Var jo("jo"), ji("ji");

    // Pure definition: y(j) = 0;
    y_func.compute_root();
    y_func.split(j, jo, ji, vec_width * 8)  // reasonably large tile; adjust if desired
          .parallel(jo)
          .vectorize(ji, vec_width);

    // Reduction update: y(j) += A(j, r2) * tmp(r2)
    y_func.update()
          // Split j into tiles [jo, ji]
          .split(j, jo, ji, vec_width * 8)
          // Reorder so that within each tile we have:
          //   for jo (parallel over tiles)
          //     for r2 (i)
          //       for ji (contiguous j, vectorized)
